content.content:
// Learning panel: a wide overlay over the globe with the equations, worked examples and limitations.
// The text itself is plain HTML in index.html (<div id="learn">), so it can be read and edited there.
// KaTeX (loaded from the CDN in index.html) typesets the maths the first time the panel opens; if it
// did not load (no internet), the LaTeX source stays visible, which is still readable.
// The numbers in the worked examples are checked against the Python code by tests/test_learning.py.

const $ = (id) => document.getElementById(id);

export function initLearning() {
  const panel = $("learn");
  const btn = $("tab-btn-learn");
  let typeset = false;

  function open() {
    panel.hidden = false;
    btn.classList.add("active");
    btn.setAttribute("aria-selected", "true");
    if (!typeset && window.renderMathInElement) {
      window.renderMathInElement(panel, {
        delimiters: [
          { left: "\\[", right: "\\]", display: true },     // \[ ... \]  equation on its own line
          { left: "\\(", right: "\\)", display: false },    // \( ... \)  inside a sentence
        ],
        throwOnError: false,                                // a typo shows in red instead of breaking the page
      });
      typeset = true;
    }
    panel.focus();
  }

  function close() {
    panel.hidden = true;
    btn.classList.remove("active");
    btn.setAttribute("aria-selected", "false");
  }

  btn.addEventListener("click", () => (panel.hidden ? open() : close()));
  $("learn-close").addEventListener("click", close);
  document.addEventListener("keydown", (e) => { if (e.key === "Escape" && !panel.hidden) close(); });
  // the table of contents scrolls inside the panel rather than jumping the whole page
  for (const a of panel.querySelectorAll("nav a")) {
    a.addEventListener("click", (e) => {
      e.preventDefault();
      panel.querySelector(a.getAttribute("href")).scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }
}
          `<line x1="${cx}" y1="${base}" x2="${cx - R * Math.cos(a)}" y2="${base - R * Math.sin(a)}" stroke="#ff8a80"/>` +
          `<text x="${cx + 36}" y="${base - 6}" fill="#ff8a80" font-size="11">${angle}°</text>` : "") +
    `<line x1="10" y1="${base}" x2="${W - 10}" y2="${base}" stroke="#8b98a8"/>` +
    `<circle cx="${cx}" cy="${base}" r="4" fill="#ff3b30"/>` +
    `<text x="${cx}" y="${H - 4}" fill="#8b98a8" font-size="11" text-anchor="middle">receiver</text>` +
    `<text x="${cx}" y="10" fill="#8b98a8" font-size="11" text-anchor="middle">${on ? "open sky above the walls" : "open sky down to the horizon"}</text>`;
}

function setupTabs(onShow) {
  const show = (which) => {
    for (const name of TABS) {
      $(`tab-${name}`).hidden = name !== which;
      $(`tab-btn-${name}`).classList.toggle("active", name === which);
      $(`tab-btn-${name}`).setAttribute("aria-selected", name === which);
    }
    onShow(which);
  };
  for (const name of TABS) $(`tab-btn-${name}`).addEventListener("click", () => show(name));
}

async function main() {
  initLearning();          // the Learning tab opens its own wide panel; it needs no Python
  const api = await loadPython();
  loadingStep("Loading the Earth and Moon maps");
  const land = await loadLandMask("data/land_mask.json").catch((e) => { console.warn("no land grid:", e); return null; });
  const moonAlbedo = await loadMoonAlbedo("data/moon_albedo.json").catch((e) => { console.warn("no Moon grid:", e); return null; });

